solution:
def is_subsequence(typed, name):
    found = 0                                  # how many characters of `typed` have been matched so far
    for char in name:
        if found == len(typed):
            break                              # everything is matched, no need to read on
        if char == typed[found]:
            found += 1
    return found == len(typed)
